class Solution {
  public boolean verifyPreorder(int[] preorder) {
    // the array doubles as a stack; low is the value every later node must exceed
    int low = Integer.MIN_VALUE, top = -1;
    for (int x : preorder) {
      if (x < low) return false;
      while (top >= 0 && preorder[top] < x) low = preorder[top--];
      preorder[++top] = x;
    }
    return true;
  }
}
